consumer.ReceivedAsync += async (_, ea) =>
{
    try
    {
        await HandleAsync(ea.Body, ea.Redelivered);
        await ch.BasicAckAsync(ea.DeliveryTag, multiple: false);
    }
    catch (ValidationException)           // błąd trwały -> DLX
    { await ch.BasicRejectAsync(ea.DeliveryTag, requeue: false); }
    catch (Exception)                     // przejściowy -> retry kolejką z TTL lub limit
    { await ch.BasicNackAsync(ea.DeliveryTag, multiple: false, requeue: false); }
};

